1	import { cancelAccountResearchReview } from "./account-knowledge";
2	/**
3	 * Background agents — the Apparatus runs in the background, watching the
4	 * draft and building an automatic bibliography without the writer having to
5	 * ask. The model is intentionally simple:
6	 *
7	 *   1. Watch the active folio for content changes (debounced).
8	 *   2. Hand the draft to the writer's AI model, which decides what genuinely
9	 *      needs a source: a quote to attribute, a named film or book, a
10	 *      statistic, a checkable claim. Each becomes a ResearchTarget carrying
11	 *      its own precise search query.
12	 *   3. Skip targets whose passage already has a saved source or was
13	 *      researched recently (dedupe), cap the pass at a few targets.
14	 *   4. Resolve each target through the configured research provider, one
15	 *      query at a time, and merge the best hit into the bibliography with
16	 *      `provenance: "background"` so the panel can tell who found them.
17	 *   5. Stream the pass live: every state change (extract → per-claim search
18	 *      → save → outcome) updates an in-memory ledger that `snapshot()` hands
19	 *      to the UI, and each saved claim fires its own `twyne:background-sources`
20	 *      event so the panel can show sources as they land, not in a lump.
21	 *
22	 * The Convex client, a research provider, and an AI model are all required.
23	 * Missing any of those, the watcher stays a no-op — the writer still sees
24	 * their manually-saved sources.
25	 */
26	
