70	const DEBOUNCE_MS = 45_000;
71	const PASS_TTL_MS = 5 * 60_000; // don't chase the same set of claims every pass
72	const MAX_BACKGROUND_PER_FOLIO = 25; // soft cap so the bib doesn't grow forever
73	const SNIPPET_MIN_CHARS = 40; // skip throwaway stubs
74	const MIN_DRAFT_CHARS = 120; // too thin to bother an AI
75	// The signed-in free hosted tier permits five searches per minute. Extraction
76	// can queue more targets, but one immediate pass must not make the sixth fail.
77	const MAX_TARGETS_PER_PASS = 5;
78	
79	interface ResearchState {
80	  lastQuery: string;
81	  lastQueryAt: number;
82	  savedThisSession: number;
83	  lastTickAt: number;
84	  lastProvider?: string;
85	  lastStatus: "idle" | "running" | "saving" | "error";
86	  lastError?: string;
87	  /** What the watcher is doing right now, for an observable headline. */
88	  phase: "idle" | "extracting" | "searching" | "saving" | "error";
89	  /** Why the watcher is idle, so the panel never just says "watching". */
90	  idleReason: ResearchIdleReason;
91	  /** When a failed pass will try again on its own. */
92	  nextRetryAt?: number;
93	}
94	
95	/**
96	 * Why no research is running. Each one is a different thing for the writer
97	 * to know: waiting for them, nothing to do, a setup step, or a finished pass.
98	 */
99	export type ResearchIdleReason =
100	  | "waiting"
101	  | "too-short"
102	  | "no-provider"
103	  | "no-claims"
104	  | "covered"
105	  | "pass-done";
106	
107	/** The same states, short enough for a status line. */
108	export const RESEARCH_IDLE_LABEL: Record<ResearchIdleReason, string> = {
109	  waiting: "Waiting for a pause",
110	  "too-short": "Draft too short",
111	  "no-provider": "Sign in to research",
112	  "no-claims": "No claims to source",
113	  covered: "Claims covered",
114	  "pass-done": "Pass finished",
115	};
116	
117	export const RESEARCH_IDLE_COPY: Record<ResearchIdleReason, string> = {
118	  waiting: "Waiting for you to pause. Research runs after a quiet moment.",
119	  "too-short": "The draft is too short to check for claims yet.",
120	  "no-provider":
121	    "Automatic research starts when you sign in or choose an AI provider in Settings.",
122	  "no-claims":
123	    "Read the draft and found no claims that need a source right now.",
124	  covered: "Every claim it found already has a source or was just checked.",
125	  "pass-done": "Finished the last pass. Results are below.",
126	};
