128	export type ResearchTargetStatus =
129	  | "queued"
130	  | "searching"
131	  | "found"
132	  | "missed"
133	  | "error";
134	
135	/** One claim the watcher decided needs a source — the live row in the panel. */
136	export interface ResearchProgressItem {
137	  key: string;
138	  kind: string;
139	  anchor: string;
140	  query: string;
141	  status: ResearchTargetStatus;
142	  /** How many sources were saved when status is "found". */
143	  count?: number;
144	  /** Human-readable reason when the claim hit an error. */
145	  error?: string;
146	  at?: number;
147	}
148	
149	/** A settlement: the claim matched sources, came back bare, or failed loudly. */
150	export interface ResearchActivityEntry {
151	  id: string;
152	  at: number;
153	  kind: string;
154	  anchor: string;
155	  query: string;
156	  outcome: "found" | "missed" | "error";
157	  count: number;
158	  error?: string;
159	}
160	
161	interface ResearchSnapshot {
162	  lastQuery: string;
163	  lastQueryAt: number;
164	  savedThisSession: number;
165	  lastTickAt: number;
166	  status: string;
167	  error?: string;
168	  activeFolioId: string | null;
169	  provider?: string;
170	  /** The citable items the last pass wanted sources for. */
171	  lastTargets: Array<{ kind: string; anchor: string; query: string }>;
172	  /** Live per-claim pipeline state for the current/last pass. */
173	  phase: string;
174	  /** Why the watcher is idle, when it is. */
175	  idleReason: ResearchIdleReason;
176	  /** When a failed pass retries on its own, if one is scheduled. */
177	  nextRetryAt?: number;
178	  passActive: boolean;
179	  progress: ResearchProgressItem[];
180	  activity: ResearchActivityEntry[];
181	}
182	
183	const state: ResearchState = {
184	  lastQuery: "",
185	  lastQueryAt: 0,
186	  savedThisSession: 0,
187	  lastTickAt: 0,
188	  lastStatus: "idle",
189	  phase: "idle",
190	  idleReason: "waiting",
191	};
192	
193	let debounceTimer: ReturnType<typeof setTimeout> | null = null;
194	let activeClient: ConvexClient | null = null;
195	let activeBrief: ProjectBrief | null = null;
196	let activeFolioId: string | null = null;
197	/** Targets researched already this session, by stable key. */
198	let recentTargetKeys = new Set<string>();
199	let lastPassFingerprint = "";
200	let lastPassAt = 0;
201	/** The most recent draft handed to the watcher, so errors can retry. */
202	let lastDraftText = "";
203	let lastTargetSummary: Array<{ kind: string; anchor: string; query: string }> =
204	  [];
205	/** The live ledger for the current/most recent pass. */
206	let progressItems: ResearchProgressItem[] = [];
207	let activityLog: ResearchActivityEntry[] = [];
208	let passInFlight = false;
209	/**
210	 * Monotonic ownership token for async work. Providers are not all abortable,
211	 * so a folio switch invalidates an old pass before it may persist anything.
212	 */
213	let researchGeneration = 0;
214	
215	/** Failed passes retry on their own, further apart each time. */
216	const RETRY_DELAYS_MS = [30_000, 2 * 60_000, 10 * 60_000];
217	let retryAttempt = 0;
218	let retryTimer: ReturnType<typeof setTimeout> | null = null;
219	
220	function clearRetry(): void {
221	  if (retryTimer) clearTimeout(retryTimer);
222	  retryTimer = null;
223	}
224	
225	/**
226	 * Try a failed pass again later without being asked. Gives up after the
227	 * last delay and leaves the error and its retry button on screen.
228	 */
229	function scheduleRetry(): void {
230	  clearRetry();
231	  const delay = RETRY_DELAYS_MS[retryAttempt];
232	  if (delay === undefined || !lastDraftText) return;
233	  retryAttempt += 1;
234	  state.nextRetryAt = Date.now() + delay;
235	  const generation = researchGeneration;
236	  retryTimer = setTimeout(() => {
237	    retryTimer = null;
238	    state.nextRetryAt = undefined;
239	    if (generation !== researchGeneration) return;
240	    void runOnce(lastDraftText, true);
241	  }, delay);
242	}
243	
244	const MAX_PROGRESS_ROWS = 8;
245	const MAX_ACTIVITY_ROWS = 8;
246	
247	function setStatus(
248	  status: ResearchState["lastStatus"],
249	  phase: ResearchState["phase"] | undefined,
250	  error?: string,
251	): void {
252	  state.lastStatus = status;
253	  state.lastTickAt = Date.now();
254	  if (phase !== undefined) state.phase = status === "error" ? "error" : phase;
255	  if (error) state.lastError = error;
256	  else if (status !== "error") state.lastError = undefined;
257	  notify();
258	}
259	
260	/** Go idle and say why. */
261	function settle(reason: ResearchIdleReason): void {
262	  state.idleReason = reason;
263	  setStatus("idle", "idle");
264	}
265	
266	function notify(): void {
267	  if (typeof window === "undefined") return;
268	  window.dispatchEvent(
269	    new CustomEvent("twyne:background-research", { detail: snapshot() }),
270	  );
271	}
272	
273	export function snapshot(): ResearchSnapshot {
274	  return {
275	    lastQuery: state.lastQuery,
276	    lastQueryAt: state.lastQueryAt,
277	    savedThisSession: state.savedThisSession,
278	    lastTickAt: state.lastTickAt,
279	    status: state.lastStatus,
280	    error: state.lastError,
281	    activeFolioId,
282	    provider: state.lastProvider,
283	    lastTargets: lastTargetSummary,
284	    phase: state.phase,
285	    idleReason: state.idleReason,
286	    nextRetryAt: state.nextRetryAt,
287	    passActive: passInFlight,
288	    progress: [...progressItems],
289	    activity: [...activityLog],
290	  };
291	}
