293	/** Human-readable "how long ago" for the activity feed. */
294	export function formatResearchTime(ts: number): string {
295	  const seconds = Math.max(0, Math.round((Date.now() - ts) / 1000));
296	  if (seconds < 10) return "just now";
297	  if (seconds < 60) return `${seconds}s ago`;
298	  const mins = Math.round(seconds / 60);
299	  if (mins < 60) return `${mins}m ago`;
300	  const hours = Math.round(mins / 60);
301	  return `${hours}h ago`;
302	}
303	
304	function logActivity(
305	  kind: string,
306	  anchor: string,
307	  query: string,
308	  outcome: "found" | "missed" | "error",
309	  count: number,
310	  error?: string,
311	): void {
312	  activityLog.unshift({
313	    id: crypto.randomUUID(),
314	    at: Date.now(),
315	    kind,
316	    anchor,
317	    query,
318	    outcome,
319	    count,
320	    error,
321	  });
322	  if (activityLog.length > MAX_ACTIVITY_ROWS) {
323	    activityLog.length = MAX_ACTIVITY_ROWS;
324	  }
325	}
326	
327	function emitSaved(
328	  target: ResearchTarget,
329	  saved: number,
330	  folioId: string,
331	): void {
332	  if (typeof window === "undefined") return;
333	  window.dispatchEvent(
334	    new CustomEvent("twyne:background-sources", {
335	      detail: {
336	        saved,
337	        query: target.query,
338	        anchor: target.anchor,
339	        kind: target.kind,
340	        folioId,
341	      },
342	    }),
343	  );
344	}
345	
346	/* ── Outcomes, errors, retry ────────────────────────────────────── */
347	
348	/** A provider verdict on a single claim's query. */
349	export type SearchOutcome =
350	  | { ok: true; provider: string; results: Source[] }
351	  | { ok: false; message: string };
352	
353	function errorMessage(err: unknown, fallback: string): string {
354	  if (err instanceof Error && err.message) return err.message;
355	  if (typeof err === "string" && err) return err;
356	  return fallback;
357	}
358	
359	/** Re-run the last pass (extract + resolve) right now — a "try again" for
360	 *  AI/configuration failures where there's nothing to fix per-claim. Forces
361	 *  the pass through the idempotency gate so a same-set retry isn't dropped. */
362	export function retryBackgroundResearch(): void {
363	  if (!activeFolioId || !lastDraftText) return;
364	  schedule(lastDraftText, 0, true);
365	}
366	
367	/** Re-run exactly one claim against the provider — used for a claim whose
368	 *  only stumble was a timeout / network error. */
369	export function retryResearchTarget(key: string): void {
370	  const row = progressItems.find((p) => p.key === key);
371	  const folioId = activeFolioId;
372	  if (!row || passInFlight || !folioId) return;
373	  const generation = researchGeneration;
374	  const target: ResearchTarget = {
375	    id: `retry-${row.key}`,
376	    kind: row.kind as ResearchTargetKind,
377	    anchor: row.anchor,
378	    query: row.query,
379	    reason: "",
380	    importance: 1,
381	  };
382	  passInFlight = true;
383	  setStatus("running", "searching");
384	  void resolveClaim(row, target, { generation, folioId })
385	    .catch((err) => {
386	      row.status = "error";
387	      row.error = errorMessage(err, "Research failed.");
388	      logActivity(row.kind, row.anchor, row.query, "error", 0, row.error);
389	    })
390	    .finally(() => {
391	      if (generation === researchGeneration) {
392	        passInFlight = false;
393	        setStatus("idle", "idle");
394	      }
395	    });
396	}
397	
398	export interface DirectedResearchRequest extends DirectedResearchTargetInput {
399	  /** Guards a selection captured immediately before a folio switch. */
400	  folioId?: string;
401	}
402	
403	export interface ResearchCommandResult {
404	  ok: boolean;
405	  message?: string;
406	}
407	
408	/** Research exactly the passage the writer selected. This bypasses target
409	 * extraction, while keeping the normal provider, progress, retry, ranking,
410	 * and bibliography pipeline. */
411	export async function researchSelection(
412	  request: DirectedResearchRequest,
413	): Promise<ResearchCommandResult> {
414	  const folioId = activeFolioId;
415	  if (!folioId || (request.folioId && request.folioId !== folioId)) {
416	    return { ok: false, message: "That selection belongs to another folio." };
417	  }
418	  if (passInFlight) {
419	    return {
420	      ok: false,
421	      message:
422	        "The Apparatus is already searching. Wait for this pass to settle.",
423	    };
424	  }
425	  const target = directedResearchTarget(request);
426	  if (!target) return { ok: false, message: "Select a passage to research." };
427	
428	  const generation = researchGeneration;
429	  const row: ResearchProgressItem = {
430	    key: targetKey(target),
431	    kind: target.kind,
432	    anchor: target.anchor,
433	    query: target.query,
434	    status: "queued",
435	  };
436	  progressItems = [
437	    row,
438	    ...progressItems.filter((item) => item.key !== row.key),
439	  ].slice(0, MAX_PROGRESS_ROWS);
440	  lastTargetSummary = [
441	    { kind: target.kind, anchor: target.anchor, query: target.query },
442	  ];
443	  state.lastQuery = target.query;
444	  state.lastQueryAt = Date.now();
445	  passInFlight = true;
446	  setStatus("running", "searching");
447	  try {
448	    await resolveClaim(row, target, { generation, folioId });
449	    if (generation !== researchGeneration) {
450	      return {
451	        ok: false,
452	        message: "The folio changed before research finished.",
453	      };
454	    }
455	    return row.status === "error"
456	      ? { ok: false, message: row.error ?? "Research failed." }
457	      : { ok: true };
458	  } finally {
459	    if (generation === researchGeneration) {
460	      passInFlight = false;
461	      settle("pass-done");
462	      // Claims whose search broke are tried again later on their own.
463	      const failed = progressItems.filter((p) => p.status === "error");
464	      for (const row of failed) recentTargetKeys.delete(row.key);
465	      if (failed.length) scheduleRetry();
466	    }
467	  }
468	}
469	
470	/** Re-run target extraction immediately with a writer-authored direction. */
471	export async function steerBackgroundResearch(
472	  instructions: string,
473	): Promise<ResearchCommandResult> {
474	  const direction = instructions.trim();
475	  if (!direction) return { ok: false, message: "Write a direction first." };
476	  if (!activeFolioId || !lastDraftText) {
477	    return { ok: false, message: "Open a folio with draft text first." };
478	  }
479	  if (lastDraftText.trim().length < MIN_DRAFT_CHARS) {
480	    return {
481	      ok: false,
482	      message:
483	        "The folio needs a little more draft text before it can be steered.",
484	    };
485	  }
486	  if (passInFlight) {
487	    return { ok: false, message: "Let the current search settle first." };
488	  }
489	  const aiSettings = await loadAiSettingsFromIdb();
490	  if (!aiSettings || !hasConfiguredAiProvider(aiSettings)) {
491	    return {
492	      ok: false,
493	      message:
494	        "Choose an AI provider in Settings before steering a draft-wide pass.",
495	    };
496	  }
497	  await runOnce(lastDraftText, true, direction);
498	  return state.lastStatus === "error"
499	    ? { ok: false, message: state.lastError ?? "Research failed." }
500	    : { ok: true };
501	}
502	
503	/** Take one claim through search → rank → save, updating its live row and
504	 *  the activity feed as it goes. Shared by the pass loop and single retries. */
505	async function resolveClaim(
506	  row: ResearchProgressItem,
507	  target: ResearchTarget,
508	  run: { generation: number; folioId: string },
509	): Promise<void> {
510	  if (run.generation !== researchGeneration) return;
511	  const settings = await loadApparatusSettingsFromIdb();
512	  row.status = "searching";
513	  row.error = undefined;
514	  notify();
515	
516	  let outcome: SearchOutcome;
517	  try {
518	    outcome = await searchForTarget(target, settings);
519	  } catch (err) {
520	    outcome = { ok: false, message: errorMessage(err, "Search failed.") };
521	  }
522	  if (run.generation !== researchGeneration) return;
523	  if (outcome.ok) state.lastProvider = outcome.provider;
524	
525	  let found = 0;
526	  let failMsg: string | undefined;
527	  if (outcome.ok) {
528	    const ranked = rankSourcesForTarget(outcome.results);
529	    try {
530	      setStatus("running", "saving");
531	      found = await persistTarget(target, ranked, run.folioId);
532	      setStatus("running", "searching");
533	    } catch (err) {
534	      found = 0;
535	      failMsg = errorMessage(err, "Could not save the found sources.");
536	    }
537	  } else {
538	    failMsg = outcome.message;
539	  }
540	
541	  row.at = Date.now();
542	  if (found > 0) {
543	    row.status = "found";
544	    row.count = found;
545	    recentTargetKeys.add(targetKey(target));
546	    state.savedThisSession += found;
547	  } else if (failMsg) {
548	    row.status = "error";
549	    row.error = failMsg;
550	  } else {
551	    row.status = "missed";
552	    // A miss remains available for explicit retry in Deep Trace, but should
553	    // not monopolize every automatic pass and starve later dossier targets.
554	    recentTargetKeys.add(targetKey(target));
555	  }
556	  logActivity(
557	    target.kind,
558	    target.anchor,
559	    target.query,
560	    failMsg ? "error" : found > 0 ? "found" : "missed",
561	    found,
562	    failMsg,
563	  );
564	  notify();
565	  emitSaved(target, found, run.folioId);
566	}
567	
568	/** Fingerprint of a set of targets — stable identity for the TTL cache. */
569	function fingerprintOf(targets: ResearchTarget[]): string {
570	  return targets
571	    .map((t) => targetKey(t))
572	    .sort()
573	    .join("|");
574	}
575	
576	/** Re-run research now (used on folio switch and on initial load). */
577	export function kickBackgroundResearch(draftText: string): void {
578	  if (!activeFolioId) return;
579	  lastDraftText = draftText.trim();
580	  schedule(draftText, 0);
581	}
582	
583	/** Notify the watcher that the draft has changed. Debounced. */
584	export function onDraftChanged(draftText: string): void {
585	  if (!activeFolioId) return;
586	  lastDraftText = draftText.trim();
587	  schedule(draftText, DEBOUNCE_MS);
588	}
589	
590	export function stopBackgroundResearch(): void {
591	  cancelAccountResearchReview();
592	  clearRetry();
593	  retryAttempt = 0;
594	  if (debounceTimer) {
595	    clearTimeout(debounceTimer);
596	    debounceTimer = null;
597	  }
598	  researchGeneration += 1;
599	  passInFlight = false;
600	  setStatus("idle", "idle");
601	}
602	
603	/** Configure the research watcher. Safe to call repeatedly — the latest
604	 *  args win. */
605	export function startBackgroundResearch(args: {
606	  client: ConvexClient | null;
607	  brief: ProjectBrief | null;
608	  folioId: string | null;
609	}): void {
610	  cancelAccountResearchReview();
611	  clearRetry();
612	  retryAttempt = 0;
613	  researchGeneration += 1;
614	  activeClient = args.client;
615	  // Share the client with the MCP layer, which also needs it for the relay
616	  // from call sites that never receive one (the drafting tool loop).
617	  setMcpConvexClient(args.client);
618	  activeBrief = args.brief;
619	  activeFolioId = args.folioId;
620	  recentTargetKeys = new Set();
621	  progressItems = [];
622	  activityLog = [];
623	  lastTargetSummary = [];
624	  passInFlight = false;
625	  settle("waiting");
626	}
627	
628	function schedule(draftText: string, delay: number, force = false): void {
629	  if (debounceTimer) clearTimeout(debounceTimer);
630	  debounceTimer = setTimeout(() => {
631	    debounceTimer = null;
632	    void runOnce(draftText, force);
633	  }, delay);
634	}
635	
636	async function runOnce(
637	  draftText: string,
638	  force = false,
639	  steeringInstructions?: string,
640	): Promise<void> {
641	  if (!activeFolioId) return;
642	  const generation = researchGeneration;
643	  const folioId = activeFolioId;
644	  const trimmed = draftText.trim();
645	  if (trimmed.length < MIN_DRAFT_CHARS) {
646	    settle("too-short");
647	    return;
648	  }
649	
650	  // The watcher decides "what needs a source" with the writer's model when
651	  // they have one, and otherwise with the text itself and Jev on Twyne's
652	  // service. Only a signed-out writer with no model has no automatic path.
653	  const aiSettings = await loadAiSettingsFromIdb();
654	  const ownModel = !!aiSettings && hasConfiguredAiProvider(aiSettings);
655	  if (!ownModel && !activeClient) {
