      .map((e) => normalizeUrl(e.url)),
  );
  const judged = new Set<string>();
  const kept: CheckedSource[] = [];
  let searches = 0;
  let read = 0;
  let failMsg: string | undefined;

  for (const [i, query] of queries.entries()) {
    row.query = query;
